import 'package:flutter/material.dart';
import 'package:flutter_web_plugins/url_strategy.dart';

/// Path URLs (no #) are what make /word-counter a real, crawlable address.
/// The static shell for each route is generated by flutter-web-seo; this app
/// just boots on top of it and renders the same route.
void main() {
  usePathUrlStrategy();
  runApp(const DemoApp());
}

class DemoApp extends StatelessWidget {
  const DemoApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Demo app',
      initialRoute: '/',
      routes: {
        '/': (_) => const HomePage(),
        '/word-counter': (_) => const WordCounterPage(),
      },
    );
  }
}

class HomePage extends StatelessWidget {
  const HomePage({super.key});

  @override
  Widget build(BuildContext context) => Scaffold(
        appBar: AppBar(title: const Text('Demo app')),
        body: Center(
          child: FilledButton(
            onPressed: () => Navigator.pushNamed(context, '/word-counter'),
            child: const Text('Word counter'),
          ),
        ),
      );
}

class WordCounterPage extends StatefulWidget {
  const WordCounterPage({super.key});

  @override
  State<WordCounterPage> createState() => _WordCounterPageState();
}

class _WordCounterPageState extends State<WordCounterPage> {
  String _text = '';

  @override
  Widget build(BuildContext context) {
    final words =
        _text.trim().isEmpty ? 0 : _text.trim().split(RegExp(r'\s+')).length;
    return Scaffold(
      appBar: AppBar(title: const Text('Word counter')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(children: [
          TextField(
            maxLines: 8,
            onChanged: (v) => setState(() => _text = v),
            decoration: const InputDecoration(border: OutlineInputBorder()),
          ),
          const SizedBox(height: 12),
          Text('$words words, ${_text.length} characters'),
        ]),
      ),
    );
  }
}
